const WD = { Sun: 0, Mon: 1, Tue: 2, Wed: 3, Thu: 4, Fri: 5, Sat: 6 };

const WEEKEND = {
  iq: [5, 6], sa: [5, 6], kw: [5, 6], qa: [5, 6], bh: [5, 6],
  om: [5, 6], jo: [5, 6], eg: [5, 6],
  ae: [6, 0]
};

function tzParts(date, tz) {
  const dtf = new Intl.DateTimeFormat('en-US', {
    timeZone: tz, hour12: false, weekday: 'short',
    year: 'numeric', month: '2-digit', day: '2-digit',
    hour: '2-digit', minute: '2-digit', second: '2-digit'
  });
  const o = {};
  for (const p of dtf.formatToParts(date)) o[p.type] = p.value;
  if (o.hour === '24') o.hour = '00';
  return o;
}

function offsetMinutes(date, tz) {
  const p = tzParts(date, tz);
  const asUTC = Date.UTC(+p.year, +p.month - 1, +p.day, +p.hour, +p.minute, +p.second);
  return Math.round((asUTC - date.getTime()) / 60000);
}

function offsetString(mins) {
  const sign = mins < 0 ? '-' : '+';
  const a = Math.abs(mins);
  return sign + String(Math.floor(a / 60)).padStart(2, '0') + ':' + String(a % 60).padStart(2, '0');
}

function utcFromWall(y, mo, d, h, mi, s, tz) {
  const target = Date.UTC(y, mo - 1, d, h, mi, s);
  let guess = target;
  for (let i = 0; i < 4; i++) {
    const off = offsetMinutes(new Date(guess), tz);
    const next = target - off * 60000;
    if (next === guess) break;
    guess = next;
  }
  return new Date(guess);
}

const out = [];
for (const item of $input.all()) {
  const j = item.json;
  const tz = j.tz || 'Asia/Baghdad';
  const country = String(j.country || 'iq').toLowerCase();
  const audience = j.audience === 'b2b' ? 'b2b' : 'b2c';

  const base = j.ts_utc ? new Date(j.ts_utc) : new Date();
  if (isNaN(base.getTime())) {
    throw new Error('MENA Clock: invalid ts_utc "' + j.ts_utc + '" (expected ISO 8601)');
  }

  const p = tzParts(base, tz);
  const offMin = offsetMinutes(base, tz);
  const offStr = offsetString(offMin);
  const wdIdx = WD[p.weekday];
  const weekend = WEEKEND[country] || [5, 6];
  const isWeekend = weekend.indexOf(wdIdx) !== -1;

  const y = +p.year, mo = +p.month, d = +p.day;
  const dayStart = utcFromWall(y, mo, d, 0, 0, 0, tz);
  const probe = tzParts(new Date(dayStart.getTime() + 26 * 3600000), tz);
  const dayEnd = utcFromWall(+probe.year, +probe.month, +probe.day, 0, 0, 0, tz);

  let nextWork = null;
  for (let k = 0; k <= 8; k++) {
    const cand = new Date(dayStart.getTime() + k * 90000000);
    const cp = tzParts(cand, tz);
    if (weekend.indexOf(WD[cp.weekday]) !== -1) continue;
    const start = utcFromWall(+cp.year, +cp.month, +cp.day, 9, 0, 0, tz);
    if (start.getTime() > base.getTime()) { nextWork = start; break; }
  }

  out.push({ json: Object.assign({}, j, {
    tz: tz,
    country: country,
    audience: audience,
    ts_utc: base.toISOString(),
    local_iso: p.year + '-' + p.month + '-' + p.day + 'T' + p.hour + ':' + p.minute + ':' + p.second + offStr,
    local_date: p.year + '-' + p.month + '-' + p.day,
    local_hour: +p.hour,
    local_minute: +p.minute,
    utc_offset: offStr,
    utc_offset_minutes: offMin,
    weekday_local: p.weekday,
    weekday_index: wdIdx,
    is_weekend: isWeekend,
    is_workday: !isWeekend,
    next_workday_start: nextWork ? nextWork.toISOString() : null,
    local_day_start_utc: dayStart.toISOString(),
    local_day_end_utc: dayEnd.toISOString()
  }) });
}
return out;

const HIJRI_MONTHS = [
  'Muharram', 'Safar', 'Rabi al-Awwal', 'Rabi al-Thani', 'Jumada al-Ula', 'Jumada al-Akhirah',
  'Rajab', 'Shaban', 'Ramadan', 'Shawwal', 'Dhu al-Qadah', 'Dhu al-Hijjah'
];

function hijriOn(date, tz) {
  const dtf = new Intl.DateTimeFormat('en-u-ca-islamic-umalqura', {
    timeZone: tz, year: 'numeric', month: 'numeric', day: 'numeric'
  });
  const o = {};
  for (const p of dtf.formatToParts(date)) o[p.type] = p.value;
  return { y: parseInt(o.year, 10), m: parseInt(o.month, 10), d: parseInt(o.day, 10) };
}

const out = [];
for (const item of $input.all()) {
  const j = item.json;
  const tz = j.tz;
  const base = new Date(j.ts_utc);
  const h = hijriOn(base, tz);

  const isRamadan = h.m === 9;
  const isEidFitr = h.m === 10 && h.d >= 1 && h.d <= 3;
  const isEidAdha = h.m === 12 && h.d >= 10 && h.d <= 13;
  const isHajj = h.m === 12 && h.d >= 8 && h.d <= 13;

  let daysToRamadan = 0;
  if (!isRamadan) {
    daysToRamadan = null;
    for (let k = 1; k <= 380; k++) {
      const probe = hijriOn(new Date(base.getTime() + k * 86400000), tz);
      if (probe.m === 9) { daysToRamadan = k; break; }
    }
  }

  const overrides = Array.isArray(j.holiday_overrides) ? j.holiday_overrides : [];
  let holiday = null;
  for (const o of overrides) {
    if (!o || !o.date) continue;
    const scope = String(o.country || '*').toLowerCase();
    if (scope !== '*' && scope !== j.country) continue;
    if (String(o.date) === j.local_date) { holiday = String(o.name || 'Holiday'); break; }
  }

  out.push({ json: Object.assign({}, j, {
    hijri_year: h.y,
    hijri_month: h.m,
    hijri_day: h.d,
    hijri_month_name: HIJRI_MONTHS[h.m - 1] || String(h.m),
    is_ramadan: isRamadan,
    ramadan_day: isRamadan ? h.d : null,
    is_eid_fitr: isEidFitr,
    is_eid_adha: isEidAdha,
    is_hajj_window: isHajj,
    days_to_ramadan: daysToRamadan,
    is_holiday: holiday !== null,
    holiday_name: holiday
  }) });
}
return out;

const WD = { Sun: 0, Mon: 1, Tue: 2, Wed: 3, Thu: 4, Fri: 5, Sat: 6 };
const WEEKEND = {
  iq: [5, 6], sa: [5, 6], kw: [5, 6], qa: [5, 6], bh: [5, 6],
  om: [5, 6], jo: [5, 6], eg: [5, 6],
  ae: [6, 0]
};

function tzParts(date, tz) {
  const dtf = new Intl.DateTimeFormat('en-US', {
    timeZone: tz, hour12: false, weekday: 'short',
    year: 'numeric', month: '2-digit', day: '2-digit',
    hour: '2-digit', minute: '2-digit', second: '2-digit'
  });
  const o = {};
  for (const p of dtf.formatToParts(date)) o[p.type] = p.value;
  if (o.hour === '24') o.hour = '00';
  return o;
}
function offsetMinutes(date, tz) {
  const p = tzParts(date, tz);
  return Math.round((Date.UTC(+p.year, +p.month - 1, +p.day, +p.hour, +p.minute, +p.second) - date.getTime()) / 60000);
}
function utcFromWall(y, mo, d, h, mi, s, tz) {
  const target = Date.UTC(y, mo - 1, d, h, mi, s);
  let guess = target;
  for (let i = 0; i < 4; i++) {
    const off = offsetMinutes(new Date(guess), tz);
    const next = target - off * 60000;
    if (next === guess) break;
    guess = next;
  }
  return new Date(guess);
}

const SEND_START = 9;
const PRAYER_START = 11;
const PRAYER_END = 13;
const RAMADAN_LATE_END = 2;

function daypartFor(h, audience, isRamadan) {
  if (audience === 'b2b') {
    if (h >= 9 && h < 14) return 'business_peak';
    if (h >= 6 && h < 9) return 'morning';
    if (h >= 14 && h < 18) return 'afternoon';
    if (h >= 18 && h < 23) return 'evening';
    return 'late_night';
  }
  if (isRamadan) {
    if (h >= 22 || h < 2) return 'evening_peak';
    if (h >= 2 && h < 6) return 'late_night';
    if (h >= 6 && h < 12) return 'morning';
    if (h >= 12 && h < 17) return 'afternoon';
    return 'evening';
  }
  if (h >= 19 && h < 22) return 'evening_peak';
  if (h >= 6 && h < 12) return 'morning';
  if (h >= 12 && h < 17) return 'afternoon';
  if (h >= 17 && h < 19) return 'evening';
  if (h >= 22) return 'evening';
  return 'late_night';
}

const out = [];
for (const item of $input.all()) {
  const j = item.json;
  const tz = j.tz;
  const audience = j.audience;
  const isB2B = audience === 'b2b';
  const weekend = WEEKEND[j.country] || [5, 6];
  const base = new Date(j.ts_utc);
  const h = j.local_hour;

  const isRamadanB2C = !isB2B && j.is_ramadan;
  const sendEnd = isB2B ? 17 : (isRamadanB2C ? 24 : 21);
  const lateWindowEnd = isRamadanB2C ? RAMADAN_LATE_END : 0;

  const daypart = daypartFor(h, audience, j.is_ramadan);

  const inWindow = (h >= SEND_START && h < sendEnd) || (lateWindowEnd > 0 && h < lateWindowEnd);

  let blockReason = null;
  if (isB2B && j.is_weekend) blockReason = 'weekend';
  else if (isB2B && j.is_holiday) blockReason = 'holiday';
  else if (j.weekday_index === 5 && h >= PRAYER_START && h < PRAYER_END) blockReason = 'friday_prayer';
  else if (!inWindow) blockReason = h < SEND_START ? 'before_window' : 'after_window';

  const isSendable = blockReason === null;

  let sendAfter = null;
  if (!isSendable) {
    if (blockReason === 'friday_prayer') {
      const p = tzParts(base, tz);
      sendAfter = utcFromWall(+p.year, +p.month, +p.day, PRAYER_END, 0, 0, tz);
    } else {
      const dayStart = new Date(j.local_day_start_utc);
      for (let k = 0; k <= 9; k++) {
        const cp = tzParts(new Date(dayStart.getTime() + k * 90000000), tz);
        if (isB2B && weekend.indexOf(WD[cp.weekday]) !== -1) continue;
        const cand = utcFromWall(+cp.year, +cp.month, +cp.day, SEND_START, 0, 0, tz);
        if (cand.getTime() > base.getTime()) { sendAfter = cand; break; }
      }
    }
  }

  out.push({ json: Object.assign({}, j, {
    daypart: daypart,
    is_evening_peak: daypart === 'evening_peak',
    is_business_peak: daypart === 'business_peak',
    send_window_start_hour: SEND_START,
    send_window_end_hour: sendEnd,
    is_sendable: isSendable,
    block_reason: blockReason,
    send_after: sendAfter ? sendAfter.toISOString() : null
  }) });
}
return out;

const rows = [];
let passed = 0, failed = 0;

for (const item of $input.all()) {
  const j = item.json;
  const expect = j.expect || {};
  const misses = [];
  for (const key of Object.keys(expect)) {
    const want = expect[key];
    const got = j[key];
    if (JSON.stringify(want) !== JSON.stringify(got)) {
      misses.push(key + ': expected ' + JSON.stringify(want) + ', got ' + JSON.stringify(got));
    }
  }
  const ok = misses.length === 0;
  if (ok) passed++; else failed++;
  rows.push({
    status: ok ? 'PASS' : 'FAIL',
    case: j.case_name,
    local_iso: j.local_iso,
    failures: misses
  });
}

return [{ json: {
  suite: 'MENA Clock self-test',
  total: rows.length,
  passed: passed,
  failed: failed,
  all_passed: failed === 0,
  results: rows
} }];
